cat > js/highlight.js <<'EOF'
// Syntax highlighting for text files and Markdown code blocks: a small tokenizer, not a parser.
// `highlight(text, lang)` answers escaped HTML with `<span class="tok-*">` around comments,
// strings, numbers, keywords, types, properties and tags. The colours are in app.css, drawn from
// the theme's own tokens, so they follow light and dark. Unknown languages come back as plain text.

const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const words = (s) => `\\b(?:${s.trim().split(/\s+/).join("|")})\\b`;

const C_COMMENT = String.raw`\/\/[^\n]*|\/\*[\s\S]*?(?:\*\/|$)`;
const HASH_COMMENT = String.raw`#[^\n]*`;
const DQ = String.raw`"(?:[^"\\\n]|\\.)*"?`;
const SQ = String.raw`'(?:[^'\\\n]|\\.)*'?`;
const NUM = String.raw`\b(?:0[xX][\da-fA-F_]+|0[bB][01_]+|\d[\d_]*(?:\.\d+)?(?:[eE][+-]?\d+)?)\b`;

const JS_KW = words(`async await break case catch class const continue debugger default delete do else export extends finally for from function if import in instanceof let new of return static super switch this throw try typeof var void while with yield interface type enum implements public private protected readonly as satisfies`);
const JS_LIT = words(`true false null undefined NaN Infinity`);

/// A language is its token kinds in priority order; each is a regex source. `lead` marks a
/// kind that only counts when the text after it matches (`(?=…)` is part of the source).
const LANGS = {
  js: [["comment", C_COMMENT], ["string", String.raw`${DQ}|${SQ}|` + "`(?:[^`\\\\]|\\\\.)*`?"], ["number", NUM], ["literal", JS_LIT], ["keyword", JS_KW], ["type", String.raw`\b[A-Z][\w$]*\b`], ["fn", String.raw`[\w$]+(?=\()`]],
  json: [["property", String.raw`"(?:[^"\\\n]|\\.)*"(?=\s*:)`], ["string", DQ], ["number", String.raw`-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?`], ["literal", words("true false null")]],
  css: [["comment", String.raw`\/\*[\s\S]*?(?:\*\/|$)`], ["string", `${DQ}|${SQ}`], ["keyword", String.raw`@[\w-]+`], ["number", String.raw`#[\da-fA-F]{3,8}\b|-?\d*\.?\d+(?:px|em|rem|%|vh|vw|s|ms|deg|fr)?\b`], ["property", String.raw`[\w-]+(?=\s*:)`], ["type", String.raw`[.#][\w-]+`]],
  html: [["comment", String.raw`<!--[\s\S]*?(?:-->|$)`], ["tag", String.raw`<\/?[A-Za-z][\w:-]*|\/?>`], ["property", String.raw`[\w:-]+(?==)`], ["string", `${DQ}|${SQ}`]],
  py: [["comment", HASH_COMMENT], ["string", String.raw`"""[\s\S]*?(?:"""|$)|'''[\s\S]*?(?:'''|$)|[rbfRBF]?(?:${DQ}|${SQ})`], ["number", NUM], ["literal", words("True False None")], ["keyword", words(`and as assert async await break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield self match case`)], ["type", String.raw`\b[A-Z]\w*\b`], ["fn", String.raw`\w+(?=\()`]],
  rust: [["comment", C_COMMENT], ["string", String.raw`r#*"[\s\S]*?(?:"#*|$)|${DQ}|b?'(?:[^'\\\n]|\\.)'`], ["number", NUM], ["literal", words("true false")], ["keyword", words(`as async await break const continue crate dyn else enum extern fn for if impl in let loop match mod move mut pub ref return self Self static struct super trait type unsafe use where while`)], ["type", String.raw`\b[A-Z]\w*\b`], ["macro", String.raw`\w+!(?=[(\[{])`], ["fn", String.raw`\w+(?=\()`]],
  go: [["comment", C_COMMENT], ["string", String.raw`${DQ}|${SQ}|` + "`[^`]*`?"], ["number", NUM], ["literal", words("true false nil iota")], ["keyword", words(`break case chan const continue default defer else fallthrough for func go goto if import interface map package range return select struct switch type var`)], ["type", String.raw`\b[A-Z]\w*\b`], ["fn", String.raw`\w+(?=\()`]],
  sh: [["comment", String.raw`(?:^|(?<=\s))#[^\n]*`], ["string", `${DQ}|${SQ}`], ["property", String.raw`\$\{?\w+\}?`], ["number", NUM], ["keyword", words(`if then else elif fi for while until do done case esac in function return export local set unset source alias exit`)]],
  yaml: [["comment", String.raw`(?:^|(?<=\s))#[^\n]*`], ["property", String.raw`^[ \t-]*[\w."/-]+(?=\s*:(?:\s|$))`], ["string", `${DQ}|${SQ}`], ["number", String.raw`-?\b\d+(?:\.\d+)?\b`], ["literal", words("true false null yes no")]],
  toml: [["comment", HASH_COMMENT], ["tag", String.raw`^\s*\[[^\]\n]*\]`], ["property", String.raw`^[ \t]*[\w."-]+(?=\s*=)`], ["string", `${DQ}|${SQ}`], ["number", NUM], ["literal", words("true false")]],
  sql: [["comment", String.raw`--[^\n]*|\/\*[\s\S]*?(?:\*\/|$)`], ["string", SQ], ["number", NUM], ["keyword", String.raw`\b(?:select|from|where|insert|into|values|update|set|delete|create|alter|drop|table|index|join|left|right|inner|outer|on|group|by|order|having|limit|offset|and|or|not|null|as|in|is|like|distinct|union|primary|key|foreign|references|default|unique|case|when|then|else|end)\b`.replace(/\\b\(\?:/, "(?i:\\b(?:").replace(/\)\\b$/, ")\\b)")]],
};

const ALIASES = {
  js: "js", jsx: "js", mjs: "js", cjs: "js", ts: "js", tsx: "js", javascript: "js", typescript: "js", java: "js", c: "js", h: "js", cpp: "js", cc: "js", cs: "js", swift: "js", kt: "js", php: "js",
  json: "json", jsonc: "json", json5: "json", webmanifest: "json",
  css: "css", scss: "css", less: "css",
  html: "html", htm: "html", xml: "html", svg: "html", vue: "html", svelte: "html",
  py: "py", python: "py", rb: "py", ruby: "py",
  rs: "rust", rust: "rust", go: "go",
  sh: "sh", bash: "sh", zsh: "sh", shell: "sh", env: "sh",
  yaml: "yaml", yml: "yaml", toml: "toml", sql: "sql",
};

const compiled = new Map();
function grammar(lang) {
  if (!compiled.has(lang)) {
    const kinds = LANGS[lang];
    const re = new RegExp(kinds.map(([, src]) => `(${src})`).join("|"), "gm");
    compiled.set(lang, { kinds: kinds.map(([k]) => k), re });
  }
  return compiled.get(lang);
}

/// The language a file name or fence tag stands for, or null.
export function langOf(nameOrTag) {
  const s = String(nameOrTag || "").toLowerCase();
  const ext = s.includes(".") ? s.split(".").pop() : s;
  return ALIASES[ext] || null;
}

/// Past this many characters a file is shown plain: the tokenizer runs on every keystroke.
export const MAX_HIGHLIGHT = 300_000;

export function highlight(text, lang) {
  if (!lang || !LANGS[lang] || text.length > MAX_HIGHLIGHT) return esc(text);
  const { kinds, re } = grammar(lang);
  let out = "";
  let last = 0;
  re.lastIndex = 0;
  for (let m; (m = re.exec(text)); ) {
    if (!m[0]) {
      re.lastIndex++;
      continue;
    }
    const kind = kinds[m.findIndex((g, i) => i > 0 && g !== undefined) - 1];
    out += esc(text.slice(last, m.index)) + `<span class="tok-${kind}">${esc(m[0])}</span>`;
    last = m.index + m[0].length;
  }
  return out + esc(text.slice(last));
}
