/// whose own text is transparent (the caret and selection stay the browser's).''')
s=s.replace('''  const area = h("textarea.wb-editor", { spellcheck: "false", "aria-label": name });''','''  const lang = langOf(name);
  const area = h("textarea.wb-editor", { spellcheck: "false", wrap: "off", "aria-label": name });
  const layer = h("pre.wb-hl", { "aria-hidden": "true" });
  const box = h("div.wb-code", { dataset: { hl: lang ? "on" : "off" } }, layer, area);
  let frame = 0;
  const paint = () => {
    if (!lang) return;
    layer.innerHTML = highlight(area.value, lang) + "\\n";
    sync();
  };
  const sync = () => layer.style.setProperty("translate", `${-area.scrollLeft}px ${-area.scrollTop}px`);
  const repaint = () => {
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(paint);
  };''')
